use crate::aap::caps::types::Intent;

const SYSTEM: &str = "You answer customer support questions. \
You may call the `lookup` tool to search the knowledge base. \
Answer concisely using the question, known facts, and any lookup results.";

/// Upper bound on model rounds. Each round is one `generate` call; a round that
/// returns a tool call consumes one unit of this budget.
const MAX_ROUNDS: usize = 3;

/// The only tool this node holds, per its `LLMClient<[lookup]>` scope.
const TOOL_LOOKUP: &str = "lookup";

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing question",
        Intent::TechnicalSupport => "technical support",
        Intent::AccountChange => "account change",
        Intent::GeneralInquiry => "general inquiry",
        Intent::Unknown => "unknown",
    }
}

fn base_prompt(ctx: &ConversationContext) -> String {
    let mut prompt = String::new();
    prompt.push_str("Intent: ");
    prompt.push_str(intent_label(ctx.intent));
    prompt.push('\n');
    prompt.push_str("Question: ");
    prompt.push_str(&ctx.question);
    prompt.push('\n');
    if !ctx.knowledge.is_empty() {
        prompt.push_str("Known facts:\n");
        for fact in &ctx.knowledge {
            prompt.push_str("- ");
            prompt.push_str(fact);
            prompt.push('\n');
        }
    }
    prompt
}

struct Node;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // The `requires` clause (len(question) <= 512) holds for every input
        // this node is given, so no check is repeated here.
        let mut prompt = base_prompt(&ctx);

        for _ in 0..MAX_ROUNDS {
            match crate::aap::caps::tool_llm::generate(SYSTEM, &prompt) {
                crate::aap::caps::tool_llm::Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                crate::aap::caps::tool_llm::Reply::Call(req) => {
                    if req.tool != TOOL_LOOKUP {
                        return ResponseResult::Error(LlmError {
                            message: format!("tool not in scope: {}", req.tool),
                        });
                    }

                    let hits = crate::aap::caps::kb_read::lookup(&req.query);

                    prompt.push_str("\nLookup for \"");
                    prompt.push_str(&req.query);
                    prompt.push_str("\" returned:\n");
                    if hits.is_empty() {
                        prompt.push_str("(no results)\n");
                    } else {
                        for hit in &hits {
                            prompt.push_str("- ");
                            prompt.push_str(hit);
                            prompt.push('\n');
                        }
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-call budget exhausted without a final answer".into(),
        })
    }
}

export!(Node);
